/**
 * node-pty bridge shim - node-pty API backed by the QiLin gateway
 * terminal ports (REST + WS data plane) instead of a native pty.
 *
 * Why: the native node-pty posix_spawn is unavailable in this
 * environment; the QiLin gateway already owns a Python asyncio+pty
 * engine (qilin/ports TerminalPort) that works everywhere. Plugins
 * keep using the node-pty API surface they know:
 *
 *   const pty = require("node-pty");
 *   const p = pty.spawn(file, args, { name, cwd, env, cols, rows });
 *   p.onData(cb); p.onExit(cb); p.write(data); p.resize(cols, rows); p.kill();
 *
 * Semantics notes:
 * - spawn() returns a facade immediately; the underlying gateway
 *   terminal is created asynchronously and early write/resize calls
 *   are queued until it is ready.
 * - Output rides the gateway WS stream (binary frames uuid + bytes).
 * - All terminals live under the reserved thread "__pty_bridge__".
 * - Requires QILIN_AUTH_DISABLED=1 (or a trusted loopback deployment):
 *   the bridge does not carry user credentials.
 */

"use strict";

const GATEWAY = (process.env.QILIN_GATEWAY_URL || "http://127.0.0.1:28081").replace(/\/$/, "");
const BRIDGE_THREAD = "__pty_bridge__";
const WS_ORIGIN = GATEWAY.replace(/^http/, "ws");

function api(method, path, body) {
  return fetch(GATEWAY + path, {
    method,
    headers: body ? { "content-type": "application/json" } : undefined,
    body: body ? JSON.stringify(body) : undefined,
  }).then(async (res) => {
    if (!res.ok) throw new Error(method + " " + path + " -> " + res.status);
    return res.json();
  });
}

class PtyBridge {
  constructor(opts) {
    this._ready = false;
    this._queue = [];
    this._dataCbs = [];
    this._exitCbs = [];
    this.uuid = null;
    this.pid = 0;
    this._opts = opts || {};
    this._init();
  }

  async _init() {
    try {
      const created = await api("POST", "/api/threads/" + BRIDGE_THREAD + "/terminals", {
        title: "node-pty bridge",
        command: "",
      });
      this.uuid = created.uuid;
      this._flush();
      this._pump();
    } catch (err) {
      console.error("[node-pty bridge] init failed:", err.message);
      for (const cb of this._exitCbs) {
        try { cb({ exitCode: 1, signal: null }); } catch { /* plugin guard */ }
      }
    }
  }

  _flush() {
    for (const op of this._queue.splice(0)) {
      try { op(); } catch (err) { console.error("[node-pty bridge] queued op failed:", err.message); }
    }
  }

  _whenReady(op) {
    if (this.uuid) op();
    else this._queue.push(op);
  }

  _pump() {
    const ws = new WebSocket(WS_ORIGIN + "/api/threads/" + BRIDGE_THREAD + "/terminals/stream");
    // Node undici WebSocket defaults binary to Blob; the frame handler
    // expects ArrayBuffer (same shape as the browser client).
    ws.binaryType = "arraybuffer";
    this._ws = ws;
    ws.onopen = () => {
      ws.send(JSON.stringify({ type: "subscribe", uuid: this.uuid }));
    };
    ws.onmessage = (event) => {
      if (event.data instanceof ArrayBuffer) {
        const bytes = new Uint8Array(event.data);
        const nl = bytes.indexOf(0x0a);
        if (nl === -1) return;
        const frameUuid = new TextDecoder().decode(bytes.slice(0, nl));
        if (frameUuid !== this.uuid) return;
        const chunk = new TextDecoder().decode(bytes.slice(nl + 1));
        for (const cb of this._dataCbs) {
          try { cb(chunk); } catch { /* plugin guard */ }
        }
        return;
      }
      try {
        const evt = JSON.parse(String(event.data));
        if (evt.type === "terminal.exited" && evt.uuid === this.uuid) {
          for (const cb of this._exitCbs) {
            try { cb({ exitCode: evt.exitCode ?? 0, signal: evt.exitSignal ?? null }); } catch { /* guard */ }
          }
        }
      } catch { /* non-JSON control frame */ }
    };
  }

  onData(cb) { this._dataCbs.push(cb); }
  onExit(cb) { this._exitCbs.push(cb); }
  write(data) {
    this._whenReady(() => {
      api("POST", "/api/threads/" + BRIDGE_THREAD + "/terminals/" + this.uuid + "/send", { text: data }).catch(() => {});
    });
  }
  resize(cols, rows) {
    this._whenReady(() => {
      api("POST", "/api/threads/" + BRIDGE_THREAD + "/terminals/" + this.uuid + "/resize", { cols, rows }).catch(() => {});
    });
  }
  kill() {
    this._whenReady(() => {
      fetch(GATEWAY + "/api/threads/" + BRIDGE_THREAD + "/terminals/" + this.uuid, { method: "DELETE" }).catch(() => {});
    });
  }
}

function spawn(file, args, opts) {
  // file/args (e.g. /bin/zsh --login) are absorbed by the gateway
  // terminal, which spawns its own login shell; cwd/cols/rows map 1:1.
  return new PtyBridge(opts);
}

module.exports = { spawn };
module.exports.default = module.exports;